package android.content;import java.util.*;public class Intent {String action;Map<String,Object> extras=new HashMap<>();public Intent(){}public Intent(Context c,Class<?> k){}public Intent setAction(String a){action=a;return this;}public String getAction(){return action;}public Intent putExtra(String k,String v){extras.put(k,v);return this;}public Intent putExtra(String k,int v){extras.put(k,v);return this;}public Intent putExtra(String k,boolean v){extras.put(k,v);return this;}public String getStringExtra(String k){return (String)extras.get(k);}public int getIntExtra(String k,int d){Object v=extras.get(k);return v==null?d:(Integer)v;}public boolean getBooleanExtra(String k,boolean d){Object v=extras.get(k);return v==null?d:(Boolean)v;}}
